  ('resource-dsd-support-materials', 'tlevels-support-dsd-page', 'Official DSD Support and Teaching Materials', 'textbook', 'notes', 'https://support.tlevels.gov.uk/hc/en-gb/articles/13813213896210-Digital-Production-Design-and-Development-now-T-Level-in-Digital-Software-Development', 'Official support page linking to teaching and learning materials, curriculum support, and route-specific updates for Digital Software Development.', null, array['official', 'support', 'provider guidance', 'teaching materials', 'digital software development']::text[], array['problem-solving', 'intro-programming', 'emerging-issues', 'legislation', 'business', 'data', 'digital-environments', 'security']::text[], 10),
