insert into public.curriculum_questions (id, source_id, title, source_label, year, paper, question_type, marks, summary, expectation, practice_prompt, legacy_topic_ids, exam_metadata, reviewed, active)
values
  ('paper2-2023-q2a-ui-end-users', 'paper2-2023', 'Design the UI around end-user characteristics', 'Paper 2 2023', 2023, 'Paper 2', 'medium-open', 4, 'Explain two ways a user interface for doctors'' surgeries should take the characteristics of the end users into account.', 'The answer should link user characteristics such as age, pace, expertise, accuracy needs, or accessibility to concrete UI choices.', 'Explain two interface choices that would help busy medical staff prescribe medicine accurately.', array['business', 'intro-programming']::text[], '{}'::jsonb, false, true),
  ('paper2-2023-q2b-cia-patient-records', 'paper2-2023', 'Apply confidentiality and integrity to patient records', 'Paper 2 2023', 2023, 'Paper 2', 'medium-open', 4, 'Describe how confidentiality and integrity of patient records apply in a new digital system.', 'A strong answer explains what must be protected, who should access it, and how accuracy and unauthorised change are controlled.', 'Explain how confidentiality and integrity should shape a digital patient records system.', array['security', 'legislation']::text[], '{}'::jsonb, false, true),
  ('paper2-2023-q3-quality-service', 'paper2-2023', 'Meet user needs and provide quality service', 'Paper 2 2023', 2023, 'Paper 2', 'short-open', 3, 'Explain one way to ensure a digital system provides a quality service that meets user needs.', 'Good answers connect one design or support decision directly to user satisfaction, reliability, usability, or outcome quality.', 'Explain one practical way a team can keep a digital service useful for its users.', array['business']::text[], '{}'::jsonb, false, true),
  ('paper2-2023-q4c-firewall', 'paper2-2023', 'Describe how a firewall improves security', 'Paper 2 2023', 2023, 'Paper 2', 'short-open', 3, 'Describe how a firewall is used to improve security in an organisation.', 'The answer should explain traffic filtering or blocking and link that control to risk reduction.', 'Describe how a firewall cuts the risk of unauthorised access or harmful traffic.', array['security', 'digital-environments']::text[], '{}'::jsonb, false, true),
  ('paper2-2023-q5-change-drivers', 'paper2-2023', 'Unforeseen factors that trigger change', 'Paper 2 2023', 2023, 'Paper 2', 'medium-open', 4, 'Describe two unforeseen factors that could trigger change in an organisation.', 'Better answers identify a realistic change trigger and explain why it forces the organisation or system to adapt.', 'Describe two unexpected events that could force a software product or organisation to change.', array['business']::text[], '{}'::jsonb, false, true),
  ('paper2-2023-q7-data-access-permissions', 'paper2-2023', 'Evaluate the impact of data access permissions', 'Paper 2 2023', 2023, 'Paper 2', 'extended-response', 9, 'Evaluate the impact of data access permissions on an organisation.', 'High-scoring answers balance the benefits of restricting and controlling access against operational costs, efficiency, and user needs.', 'Evaluate how data access permissions can help an organisation and also cause problems.', array['security', 'data', 'business']::text[], '{}'::jsonb, false, true),
  ('paper2-2023-q8a-virtual-environments', 'paper2-2023', 'Benefits of virtual environments in development', 'Paper 2 2023', 2023, 'Paper 2', 'medium-open', 4, 'Explain two benefits of using virtual environments to develop a multiplatform game.', 'The answer should focus on emulation, isolation, testing flexibility, or host security and link each point back to development work.', 'Explain two ways virtual environments help a team build software for different platforms.', array['digital-environments', 'security']::text[], '{}'::jsonb, false, true),
  ('paper2-2023-q8b-human-error', 'paper2-2023', 'Human error and development time', 'Paper 2 2023', 2023, 'Paper 2', 'medium-open', 4, 'Explain two ways human error could increase the development time of a software project.', 'A strong answer connects the mistake to rework, communication failure, testing delay, or wasted effort.', 'Explain two ways human mistakes can slow down software delivery.', array['business', 'intro-programming']::text[], '{}'::jsonb, false, true),
  ('aut22-q2b-remote-working-risks', 'core-paper2-autumn-2022', 'Remote working cyber threats', 'Autumn 2022 Paper 2', 2022, 'Paper 2', 'medium-open', 4, 'Identify and explain security threats that become relevant when staff work remotely.', 'Answers should pair a specific threat with a clear explanation of how it affects systems, users, or data.', 'Explain two cyber threats that become more serious when staff work remotely.', array['security']::text[], '{}'::jsonb, false, true),
  ('aut22-q4-virtual-environments', 'core-paper2-autumn-2022', 'Use virtual environments to test safely', 'Autumn 2022 Paper 2', 2022, 'Paper 2', 'medium-open', 4, 'Explain how virtual environments support effective and safe development or testing.', 'Answers should reference isolation, emulation, or security and link them to the scenario.', 'Explain how a virtual environment makes development safer or more flexible.', array['digital-environments', 'security']::text[], '{}'::jsonb, false, true),
  ('aut22-q6-business-risk', 'core-paper2-autumn-2022', 'Assess risks to a digital business service', 'Autumn 2022 Paper 2', 2022, 'Paper 2', 'short-open', 3, 'Identify a realistic business risk and explain the impact on the organisation.', 'The answer should name a risk and show the business consequence rather than stopping at a label.', 'Identify one major risk to a digital service and explain its likely business impact.', array['business', 'security']::text[], '{}'::jsonb, false, true),
  ('aut22-q7-data-tools', 'core-paper2-autumn-2022', 'Compare data warehouses, lakes, mining, and reporting', 'Autumn 2022 Paper 2', 2022, 'Paper 2', 'extended-response', 9, 'Evaluate different data storage and analysis approaches in terms of structure, storage, processing, and decision support.', 'Higher marks come from comparing the tools directly and weighing trade-offs rather than listing definitions.', 'Evaluate how a data warehouse, a data lake, data mining, and reporting differ.', array['data', 'business']::text[], '{}'::jsonb, false, true),
  ('paper1-practice-requirements-attendance-app', 'curated-paper1-practice', 'Separate functional and non-functional requirements', 'Paper 1 practice', null, 'Paper 1', 'short-open', 3, 'State one functional requirement and one non-functional requirement for a school attendance app.', 'Strong answers clearly separate what the system must do from how well, how safely, or how quickly it must do it.', 'State one functional requirement and one non-functional requirement for a school attendance app.', array['problem-solving', 'business', 'security']::text[], '{}'::jsonb, false, true),
  ('paper1-practice-test-data-login-field', 'curated-paper1-practice', 'Choose suitable test data for a login field', 'Paper 1 practice', null, 'Paper 1', 'medium-open', 4, 'Describe suitable test data for a login field that accepts 8 to 20 characters.', 'Good answers include valid, invalid, and extreme examples, then explain what result each test should produce.', 'Describe suitable test data for a login field that accepts 8 to 20 characters.', array['intro-programming', 'problem-solving']::text[], '{}'::jsonb, false, true),
  ('paper2-practice-accessible-mobile-booking', 'curated-paper2-practice', 'Design an accessible mobile booking interface', 'Paper 2 practice', null, 'Paper 2', 'medium-open', 4, 'Explain two interface choices that would help users book appointments accurately on a mobile device.', 'Strong answers link each design choice to a real user benefit such as readability, reduced mistakes, accessibility, or faster completion.', 'Explain two interface choices that would help users book appointments accurately on a mobile device.', array['business', 'intro-programming']::text[], '{}'::jsonb, false, true),
  ('paper2-practice-cloud-deployment-remote-team', 'curated-paper2-practice', 'Evaluate cloud deployment for a distributed team', 'Paper 2 practice', null, 'Paper 2', 'extended-response', 6, 'Evaluate whether cloud deployment is a good choice for a software team working from several locations.', 'Higher-scoring answers balance benefits such as access, scaling, and collaboration against cost, control, dependency, and security concerns before reaching a judgement.', 'Evaluate whether cloud deployment is a good choice for a software team working from several locations.', array['digital-environments', 'business', 'security']::text[], '{}'::jsonb, false, true),
  ('paper2-practice-change-control-release', 'curated-paper2-practice', 'Use change control to protect a live release', 'Paper 2 practice', null, 'Paper 2', 'medium-open', 4, 'Explain how change control can reduce problems when a new feature is released to live users.', 'The answer should show that controlled documentation, approval, testing, scheduling, and communication reduce disruption and release risk.', 'Explain how change control can reduce problems when a new feature is released to live users.', array['business', 'security']::text[], '{}'::jsonb, false, true),
  ('paper2-practice-api-credentials-errors', 'curated-paper2-practice', 'Protect API credentials and handle failures safely', 'Paper 2 practice', null, 'Paper 2', 'medium-open', 4, 'Explain why an app that uses an external API should protect its credentials and handle errors carefully.', 'Good answers explain how exposed credentials create risk and why graceful error handling protects users, data, or service quality when requests fail.', 'Explain why an app that uses an external API should protect its credentials and handle errors carefully.', array['security', 'data', 'digital-environments']::text[], '{}'::jsonb, false, true),
  ('paper2-practice-feedback-methods-service', 'curated-paper2-practice', 'Compare interviews and analytics for service improvement', 'Paper 2 practice', null, 'Paper 2', 'medium-open', 4, 'Compare interviews and usage analytics when improving an online service.', 'Stronger answers compare the type of evidence each method provides, their limits, and when one method is more useful than the other.', 'Compare interviews and usage analytics when improving an online service.', array['business', 'data']::text[], '{}'::jsonb, false, true),
  ('paper2-practice-remote-team-tooling', 'curated-paper2-practice', 'Use shared tools in a remote software team', 'Paper 2 practice', null, 'Paper 2', 'medium-open', 4, 'Explain how version control and shared documentation help a remote software team deliver safely.', 'The answer should explain how traceable code changes, shared knowledge, and clearer collaboration reduce mistakes, duplication, or delivery risk.', 'Explain how version control and shared documentation help a remote software team deliver safely.', array['business', 'digital-environments']::text[], '{}'::jsonb, false, true),
  ('paper2-practice-risk-review-feature-launch', 'curated-paper2-practice', 'Judge whether a risky feature should be launched', 'Paper 2 practice', null, 'Paper 2', 'extended-response', 6, 'Evaluate whether a high-reward feature should be released when it also introduces significant security and operational risk.', 'High-mark answers weigh business benefit against security, reliability, and reputational risk, then justify a clear decision with mitigation or contingency ideas.', 'Evaluate whether a high-reward feature should be released when it also introduces major security and operational risk.', array['business', 'security']::text[], '{}'::jsonb, false, true),
  ('qb-decomposition-abstraction', 'paper1-q-and-a', 'Question bank: decomposition, pattern recognition, and abstraction', 'Paper 1 Q&A', null, 'Paper 1', 'question-bank-section', null, 'Legacy practice bank section covering decomposition, pattern recognition, and abstraction from the older core structure.', 'Useful for short-answer practice on computational thinking terms, examples, and applied problem solving.', 'Explain how decomposition, pattern recognition, and abstraction work together when solving a problem.', array['problem-solving']::text[], '{}'::jsonb, false, true),
  ('qb-validation-and-data-types', 'paper1-q-and-a', 'Question bank: data validation and data types', 'Paper 1 Q&A', null, 'Paper 1', 'question-bank-section', null, 'Legacy question-bank coverage for validation, data types, and related programming basics.', 'Good for retrieval practice around correct typing, validation checks, and basic program logic.', 'Explain why data validation and correct data typing matter in a software solution.', array['intro-programming', 'data']::text[], '{}'::jsonb, false, true),
  ('teach-pack-q-data-model-scenarios', 'teach-pack-data-models-worksheet', 'Teaching pack: choose a data model for four scenarios', 'Data models worksheet', 2025, null, 'medium-open', null, 'For an org chart, a social follow graph, a product catalogue with suppliers, and many-to-many tasks for employees, choose hierarchical, network, or relational and justify.', 'Each scenario needs a model choice plus at least one reason (cardinality, flexibility, query complexity, or redundancy).', 'Pick hierarchical, network, or relational for each scenario and justify with relationships and query needs.', array['data']::text[], '{}'::jsonb, false, true),
  ('teach-pack-q-big-data-v', 'teach-pack-big-data-worksheet', 'Teaching pack: map scenarios to a big-data V', 'Six Vs worksheet', 2025, null, 'short-open', null, 'Identify which of Volume, Velocity, Variety, Veracity, Value, or Variability best fits short scenarios (e.g. CDR scale, live sentiment, faulty sensors).', 'Correct V plus one sentence of reasoning; accept close synonyms if the logic matches.', 'Name the primary V and explain your choice in one or two sentences.', array['data']::text[], '{}'::jsonb, false, true),
  ('teach-pack-q-access-matrix', 'teach-pack-access-control-worksheet', 'Teaching pack: justify access levels in a matrix', 'Access control worksheet', 2025, null, 'medium-open', null, 'Assign Read, Write, Admin, or No access for roles (e.g. intern, analyst, IT admin) against assets (customer DB, payroll) and justify least-privilege choices.', 'Answers should reference sensitivity, segregation of duties, and why admin is rarely default for all staff.', 'Complete two cells in the matrix and explain why those access levels follow least privilege.', array['data', 'security']::text[], '{}'::jsonb, false, true),
  ('codex-paper_1-001-problem-solving-computational-thinking-state-purpose', 'codex-reviewed-paper1-exam-bank-2026', 'Problem Solving: Computational thinking 001', 'Codex reviewed Paper 1 bank', 2026, 'Paper 1', 'short-open', 1, 'A sixth-form college is preparing a booking-process model to reduce avoidable errors. Several users have low confidence with digital services. The project notes include decomposing the task into inputs, processing and outputs.

State one reason why computational thinking should be considered in this project.', 'A full-mark response should identify computational thinking, link it to the scenario, and give enough detail to show why it matters for a sixth-form college.', 'A sixth-form college is preparing a booking-process model to reduce avoidable errors. Several users have low confidence with digital services. The project notes include decomposing the task into inputs, processing and outputs.

State one reason why computational thinking should be considered in this project.', array['problem-solving']::text[], '{"paper":"paper_1","contentArea":"Problem Solving","subtopic":"Computational thinking","commandWord":"state","assessmentObjectives":["AO1a"],"stimulus":"A sixth-form college is preparing a booking-process model to reduce avoidable errors. Several users have low confidence with digital services. The project notes include decomposing the task into inputs, processing and outputs.","difficulty":"low","indicativeMarkScheme":{"type":"points_based","points":["identifies computational thinking accurately","links the point to a sixth-form college and the stated project constraint","uses relevant problem solving terminology such as decomposition or pattern recognition","explains how using computational thinking before selecting a solution affects the project outcome"],"judgementRequired":false,"modelAnswerOutline":"A full-mark response should identify computational thinking, link it to the scenario, and give enough detail to show why it matters for a sixth-form college."},"sourceReference":"Core paper 1, Content area 1: Problem solving; Computational thinking","sourceFile":"sources/digital-dsd-specification.pdf","sourceExcerptHash":"fnv1a-5e94a87c","generationBatch":"codex-reviewed-exam-bank-2026-04-11","validation":{"fitsPaperBoundary":true,"fitsCommandWord":true,"fitsMarkDemand":true,"specGrounded":true,"sourceGrounded":true,"notDuplicate":true,"scenarioDistinct":true,"answerLogicDistinct":true},"examinerRationale":"Kept after examiner-style review because the stem is contextual, uses a valid command word, has realistic mark demand, and is grounded in the mapped specification area.","reviewDecision":"keep","duplicationRisk":"low","realismScore":8,"scenarioSignature":"paper_1:problem-solving:problem-solving-1:state-purpose","answerLogicSignature":"paper_1:problem-solving:computational-thinking:state-purpose:1","responseFormat":"written"}'::jsonb, true, true),
